def _fold(text: str) -> str:
    # Copia congelada de app.text.fold: una migración no debe importar código de la
    # aplicación, porque ese código cambiará y la migración tiene que seguir dando el
    # mismo resultado cuando se ejecute dentro de un año.
    decomposed = unicodedata.normalize("NFD", " ".join(text.split()).lower())
    return "".join(c for c in decomposed if unicodedata.category(c) != "Mn")


def _backfill_search_text() -> None:
    """Rellena search_text de los libros que ya existían (los del importador)."""
    books = sa.table("books", sa.column("id"), sa.column("title"), sa.column("search_text"))
    authors = sa.table("authors", sa.column("id"), sa.column("name"))
    book_authors = sa.table("book_authors", sa.column("book_id"), sa.column("author_id"))

    conn = op.get_bind()
    names: dict[int, list[str]] = {}
    rows = conn.execute(
        sa.select(book_authors.c.book_id, authors.c.name).join(
            authors, authors.c.id == book_authors.c.author_id
        )
    )
    for book_id, name in rows:
        names.setdefault(book_id, []).append(name)
    for book_id, title in conn.execute(sa.select(books.c.id, books.c.title)).all():
        text = _fold(" ".join([title, *names.get(book_id, [])]))
        conn.execute(books.update().where(books.c.id == book_id).values(search_text=text))


